7	// ROT13 decode function
8	function rot13(text: string): string {
9	  return text.replace(/[a-zA-Z]/g, (char) => {
10	    const base = char <= "Z" ? 65 : 97;
11	    return String.fromCharCode(((char.charCodeAt(0) - base + 13) % 26) + base);
12	  });
13	}
