154	// Generate valid groupings for 9 consonants (2-3 spaces, groups of 2+ letters)
155	function generateGrouping(): number[] {
156	  // Valid groupings for 9 consonants with 2-3 spaces, all groups >= 2
157	  const validGroupings = [
158	    [2, 2, 2, 3], // MS SN GV WLS
159	    [2, 2, 3, 2], // MS SN GVW LS
160	    [2, 3, 2, 2], // MS SNG VW LS
161	    [3, 2, 2, 2], // MSS NG VW LS
162	    [3, 3, 3], // MSS NGV WLS
163	    [3, 2, 4], // MSS NG VWLS
164	    [2, 3, 4], // MS SNG VWLS
165	    [4, 3, 2], // MSSN GVW LS
166	    [2, 4, 3], // MS SNGV WLS
167	    [3, 4, 2], // MSS NGVW LS
168	  ];
169	  return validGroupings[Math.floor(Math.random() * validGroupings.length)];
170	}
