173	function AnimatedTitle(): React.ReactElement {
174	  const [phase, setPhase] = useState<
175	    "full" | "fading" | "collapsed" | "condensed"
176	  >("full");
177	
178	  // Original title
179	  const fullText = "MISSING VOWELS";
180	
181	  // Generate random grouping once on mount
182	  const grouping = useMemo(() => generateGrouping(), []);
183	
184	  useEffect(() => {
185	    // 1s: start fading vowels (0.5s fade)
186	    const fadeTimer = setTimeout(() => setPhase("fading"), 1000);
187	    // 1.5s: collapse vowels to zero width
188	    const collapseTimer = setTimeout(() => setPhase("collapsed"), 1500);
189	    // 1.9s: add spaces between groups
190	    const condenseTimer = setTimeout(() => setPhase("condensed"), 1900);
191	    return () => {
192	      clearTimeout(fadeTimer);
193	      clearTimeout(collapseTimer);
194	      clearTimeout(condenseTimer);
195	    };
196	  }, []);
197	
198	  // Build consonant positions from grouping
199	  const consonantPositions = useMemo(() => {
200	    const positions: { group: number; pos: number }[] = [];
201	    for (let g = 0; g < grouping.length; g++) {
202	      for (let p = 0; p < grouping[g]; p++) {
203	        positions.push({ group: g, pos: p });
204	      }
205	    }
206	    return positions;
207	  }, [grouping]);
208	
209	  // Build letter elements with animation classes
210	  const letters = useMemo(() => {
211	    const result: React.ReactElement[] = [];
212	    let consonantIndex = 0;
213	
214	    for (let i = 0; i < fullText.length; i++) {
215	      const char = fullText[i];
216	
217	      if (char === " ") {
218	        result.push(
219	          <span
220	            key={i}
221	            className={`title-space ${phase === "collapsed" || phase === "condensed" ? "hidden" : ""}`}
222	          >
223	            {" "}
224	          </span>,
225	        );
226	      } else if (VOWELS.has(char)) {
227	        const vowelClass =
228	          phase === "full" ? "" : phase === "fading" ? "fade-out" : "collapse";
229	        result.push(
230	          <span key={i} className={`title-letter title-vowel ${vowelClass}`}>
231	            {char}
232	          </span>,
233	        );
234	      } else {
235	        const posInfo = consonantPositions[consonantIndex];
236	        const isGroupStart = posInfo.pos === 0 && posInfo.group > 0;
237	        consonantIndex++;
238	
239	        result.push(
240	          <span
241	            key={i}
242	            className={`title-letter title-consonant ${isGroupStart && phase === "condensed" ? "group-start" : ""}`}
243	          >
244	            {char}
245	          </span>,
246	        );
247	      }
248	    }
249	
250	    return result;
251	  }, [phase, consonantPositions]);
252	
253	  return <h1 className="animated-title">{letters}</h1>;
254	}
